<div class="page-heading"><div><span class="eyebrow">Trazabilidad global</span><h1>Auditoría del SaaS</h1><p>Consulta eventos de seguridad, configuración y gestión sin exponer contraseñas ni datos clínicos.</p></div><span class="badge badge-gray">Últimos <?= count($entries) ?> eventos</span></div>
<section class="ios-card mt-6 overflow-hidden"><div class="border-b border-slate-100 p-4 sm:p-5"><form method="get" action="<?= e(url('/admin/auditoria')) ?>" class="flex flex-col gap-3 md:flex-row"><select name="tenant_id" class="input h-10 md:flex-1"><option value="">Todas las empresas</option><?php foreach ($tenants as $tenant): ?><option value="<?= (int) $tenant['id'] ?>"<?= selected($tenantId, $tenant['id']) ?>><?= e($tenant['razonsocial']) ?></option><?php endforeach; ?></select><select name="accion" class="input h-10 md:flex-1"><option value="">Todas las acciones</option><?php foreach ($actions as $actionItem): ?><option value="<?= e($actionItem) ?>"<?= selected($action, $actionItem) ?>><?= e($actionItem) ?></option><?php endforeach; ?></select><button class="btn-secondary h-10" type="submit"><?= icon('filter', 'h-4 w-4') ?> Filtrar</button><?php if ($tenantId || $action): ?><a href="<?= e(url('/admin/auditoria')) ?>" class="btn-ghost h-10">Limpiar</a><?php endif; ?></form></div>
<?php if ($entries === []): ?><div class="empty-state"><span class="empty-icon"><?= icon('shield-plain', 'h-7 w-7') ?></span><h3>No hay eventos con estos filtros</h3><p>La actividad aparecerá aquí a medida que los usuarios utilicen la plataforma.</p></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Acción</th><th>Actor</th><th>Empresa</th><th>Entidad</th><th>IP</th><th>Detalle</th></tr></thead><tbody><?php foreach ($entries as $entry): ?><tr><td><time class="whitespace-nowrap text-xs text-slate-500"><?= format_date($entry['created_at']) ?><span class="mt-0.5 block text-[10px] text-slate-400"><?= e(date('H:i:s', strtotime($entry['created_at']))) ?></span></time></td><td><p class="max-w-[240px] text-xs font-semibold text-slate-700"><?= e($entry['accion']) ?></p></td><td><p class="text-xs text-slate-600"><?= e($entry['usuario'] ?? 'Sistema / anónimo') ?></p><p class="mt-0.5 text-[10px] text-slate-400"><?= e($entry['email'] ?? 'sin sesión') ?></p></td><td><p class="max-w-[170px] truncate text-xs text-slate-600"><?= e($entry['razonsocial'] ?? 'Plataforma') ?></p></td><td><span class="badge badge-gray"><?= e($entry['entidad']) ?><?= $entry['entidad_id'] ? ' #' . (int) $entry['entidad_id'] : '' ?></span></td><td><code class="text-[10px] text-slate-500"><?= e($entry['ip_address']) ?></code></td><td><?php $details = json_decode($entry['detalles_json'], true); if ($details): ?><details><summary class="cursor-pointer text-xs font-medium text-blue-600">Ver JSON</summary><pre class="mt-2 max-w-xs overflow-auto rounded-xl bg-slate-950 p-3 text-[10px] leading-4 text-slate-200"><?= e(json_encode($details, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)) ?></pre></details><?php else: ?><span class="text-xs text-slate-300">—</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
